from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")
        if start >= end:
            raise ValueError("Appointment end must be after start.")
        if not self.is_free(doctor, start, end):
            raise ValueError("The doctor is not free during the requested time.")
        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "blocked": True,  # active or cancelled-but-blocked
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appt = self._appointments.get(appointment_id)
        if appt is None:
            raise ValueError(f"Unknown appointment id: {appointment_id}")
        if not appt["blocked"]:
            return
        if appt["start"] - now < timedelta(hours=24):
            # Too close to start; keep the slot blocked.
            return
        appt["blocked"] = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if not appt["blocked"]:
                continue
            if appt["doctor"] != doctor:
                continue
            # Overlap check: only touching does not overlap.
            if appt["start"] < end and start < appt["end"]:
                return False
        return True
